var i=`0912-har-gow`;var a=`world-0912`;var n=`CN`;var s=`east-asia`;var o=8;var r=62;var l={en:`Har Gow`,ua:`Хар гау`};var h={en:`Har Gow is a China dish made with wheat starch, tapioca starch, shrimp, bamboo shoots. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Хар гау, страва кухні країни Китай. Основні складники: пшеничний крохмаль, тапіоковий крохмаль, креветка, пагони бамбука. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 12 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 12 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:12,i:[[`wheat-starch`,215,`g`],[`tapioca-starch`,75,`g`],[`water`,260,`ml`],[`canola-oil`,25,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`shrimp`,560,`g`],[`bamboo-shoots`,100,`g`],[`sesame-oil`,15,`ml`],[`white-peppercorn`,2,`g`],[`table-salt`,null,`to_taste`]]},{en:`Enclose shrimp filling in thin translucent wheat-and-tapioca dough and pleat each har gow delicately before steaming.`,ua:`Загорніть креветкову начинку в тонке напівпрозоре тісто з пшеничного й тапіокового крохмалю та обережно складіть хар гау складками перед пропарюванням.`,t:[`rolling-stuffed-food`],m:24,i:[]},{en:`Steam the prepared portions in a covered steamer over gently boiling water for about 13 minutes until completely cooked or set, then remove carefully.`,ua:`Готуйте підготовлені порції на парі під кришкою над слабко киплячою водою близько 13 хвилин до повної готовності чи застигання, обережно вийміть.`,t:[`steaming`],m:13,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`light-soy-sauce`,35,`ml`]]}];var g={slug:i,id:a,country:`CN`,region:s,servings:8,minutes:62,title:l,text:h,steps:m};export{n as country,g as default,a as id,r as minutes,s as region,o as servings,i as slug,m as steps,h as text,l as title};